import 'package:flutter/material.dart';
import 'package:flutter_spinkit/flutter_spinkit.dart';

// 전체 화면 로딩 오버레이
class LoadingOverlay extends StatelessWidget {
  final bool isLoading;
  final Widget child;
  final Color? color;

  const LoadingOverlay({
    super.key,
    required this.isLoading,
    required this.child,
    this.color,
  });

  @override
  Widget build(BuildContext context) {
    return Stack(
      children: [
        child,
        if (isLoading)
          Container(
            color: Colors.black.withOpacity(0.5),
            child: Center(
              child: SpinKitFadingCircle(
                color: color ?? Colors.white,
                size: 60,
              ),
            ),
          ),
      ],
    );
  }
}

// 로딩 버튼
class LoadingButton extends StatelessWidget {
  final bool isLoading;
  final String text;
  final VoidCallback? onPressed;
  final Color? color;

  const LoadingButton({
    super.key,
    required this.isLoading,
    required this.text,
    this.onPressed,
    this.color,
  });

  @override
  Widget build(BuildContext context) {
    return ElevatedButton(
      onPressed: isLoading ? null : onPressed,
      style: ElevatedButton.styleFrom(
        backgroundColor: color ?? Theme.of(context).primaryColor,
        minimumSize: const Size(double.infinity, 48),
      ),
      child: isLoading
          ? const SpinKitThreeBounce(
              color: Colors.white,
              size: 20,
            )
          : Text(text, style: const TextStyle(color: Colors.white)),
    );
  }
}

// 사용 예시
class LoadingExampleScreen extends StatefulWidget {
  const LoadingExampleScreen({super.key});

  @override
  State<LoadingExampleScreen> createState() => _LoadingExampleScreenState();
}

class _LoadingExampleScreenState extends State<LoadingExampleScreen> {
  bool _isPageLoading = false;
  bool _isButtonLoading = false;

  Future<void> _loadPage() async {
    setState(() => _isPageLoading = true);
    await Future.delayed(const Duration(seconds: 2));
    setState(() => _isPageLoading = false);
  }

  Future<void> _submitForm() async {
    setState(() => _isButtonLoading = true);
    await Future.delayed(const Duration(seconds: 2));
    setState(() => _isButtonLoading = false);
  }

  @override
  Widget build(BuildContext context) {
    return LoadingOverlay(
      isLoading: _isPageLoading,
      child: Scaffold(
        appBar: AppBar(title: const Text('로딩 예시')),
        body: Padding(
          padding: const EdgeInsets.all(16),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              ElevatedButton(
                onPressed: _loadPage,
                child: const Text('전체 화면 로딩'),
              ),
              const SizedBox(height: 24),
              LoadingButton(
                isLoading: _isButtonLoading,
                text: '제출하기',
                onPressed: _submitForm,
              ),
            ],
          ),
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_spinkit/flutter_spinkit.dart';

class AdvancedSpinnerExample extends StatefulWidget {
  const AdvancedSpinnerExample({super.key});

  @override
  State<AdvancedSpinnerExample> createState() => _AdvancedSpinnerExampleState();
}

class _AdvancedSpinnerExampleState extends State<AdvancedSpinnerExample>
    with SingleTickerProviderStateMixin {
  late AnimationController _controller;
  double _speed = 1.0;
  double _size = 50.0;
  Color _color = Colors.blue;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1200),
    );
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('고급 설정')),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          children: [
            // 스피너 표시
            Expanded(
              child: Center(
                child: SpinKitFadingCircle(
                  color: _color,
                  size: _size,
                  controller: _controller,
                  duration: Duration(
                    milliseconds: (1200 / _speed).round(),
                  ),
                ),
              ),
            ),
            // 속도 조절
            Row(
              children: [
                const Text('속도:'),
                Expanded(
                  child: Slider(
                    value: _speed,
                    min: 0.5,
                    max: 3.0,
                    divisions: 5,
                    label: '${_speed}x',
                    onChanged: (value) {
                      setState(() => _speed = value);
                    },
                  ),
                ),
              ],
            ),
            // 크기 조절
            Row(
              children: [
                const Text('크기:'),
                Expanded(
                  child: Slider(
                    value: _size,
                    min: 30,
                    max: 100,
                    divisions: 7,
                    label: '${_size.round()}',
                    onChanged: (value) {
                      setState(() => _size = value);
                    },
                  ),
                ),
              ],
            ),
            // 색상 선택
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceEvenly,
              children: [
                _colorButton(Colors.blue),
                _colorButton(Colors.red),
                _colorButton(Colors.green),
                _colorButton(Colors.purple),
                _colorButton(Colors.orange),
              ],
            ),
            const SizedBox(height: 16),
            // 재생/정지 버튼
            Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                ElevatedButton(
                  onPressed: () => _controller.repeat(),
                  child: const Text('재생'),
                ),
                const SizedBox(width: 16),
                ElevatedButton(
                  onPressed: () => _controller.stop(),
                  child: const Text('정지'),
                ),
                const SizedBox(width: 16),
                ElevatedButton(
                  onPressed: () => _controller.reset(),
                  child: const Text('리셋'),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }

  Widget _colorButton(Color color) {
    return GestureDetector(
      onTap: () => setState(() => _color = color),
      child: Container(
        width: 40,
        height: 40,
        decoration: BoxDecoration(
          color: color,
          shape: BoxShape.circle,
          border: _color == color
              ? Border.all(color: Colors.black, width: 3)
              : null,
        ),
      ),
    );
  }
}

